{
                "ability": "webmastery-site-toolkit-for-mcp/update-post",
                "label": "wstm122 denied post write preserves metadata",
                "role": "subscriber",
                "input": {
                    "post_id": "__post_id__",
                    "yoast_meta_description": "Denied\\meta"
                },
                "expect": "failure",
                "expect_error_code": "invalid_input",
                "expect_error_reason": "ability_invalid_input",
                "expect_error_shape": "canonical",
                "assert_unchanged": true,
                "assert_metadata_boundary": true,
                "assert_missing_paths": [
                    "data"
                ],
                "assert_post_meta": [
                    {
                        "post_id": "__post_id__",
                        "meta_key": "_yoast_wpseo_metadesc",
                        "value": "\\\\server\\share\\"
                    }
                ]
            }

{
                "ability": "webmastery-site-toolkit-for-mcp/update-page",
                "label": "wstm122 denied page write preserves metadata",
                "role": "subscriber",
                "input": {
                    "page_id": "__page_id__",
                    "yoast_meta_description": "Denied\\meta"
                },
                "expect": "failure",
                "expect_error_code": "invalid_input",
                "expect_error_reason": "ability_invalid_input",
                "expect_error_shape": "canonical",
                "assert_unchanged": true,
                "assert_metadata_boundary": true,
                "assert_missing_paths": [
                    "data"
                ],
                "assert_post_meta": [
                    {
                        "post_id": "__page_id__",
                        "meta_key": "_yoast_wpseo_metadesc",
                        "value": "{\"regex\":\"\\\\d+\\w\"}"
                    }
                ]
            }

{
                "ability": "webmastery-site-toolkit-for-mcp/update-post",
                "label": "wstm120 contributor cannot update unrelated draft",
                "role": "contributor",
                "input": {
                    "post_id": "__wstm120_other_draft_id__",
                    "title": "Must not change",
                    "content": "Must not change",
                    "slug": "wstm120-denied-other",
                    "yoast_meta_description": "Must not change"
                },
                "expect": "failure",
                "expect_error_code": "invalid_input",
                "expect_error_reason": "ability_invalid_input",
                "expect_error_shape": "canonical",
                "assert_permission": "invalid_input",
                "assert_unchanged": true,
                "assert_metadata_boundary": true,
                "assert_missing_paths": [
                    "data"
                ],
                "assert_capabilities": [
                    {
                        "capability": "edit_posts",
                        "args": [],
                        "allowed": true
                    },
                    {
                        "capability": "edit_post",
                        "args": [
                            "__wstm120_other_draft_id__"
                        ],
                        "allowed": false
                    }
                ]
            }

